#include "mgt_cuda/mlp_batch_norm_forward.cuh"
#include "mgt_cuda/allreduce_nccl.cuh"
#include "mgt/config.hpp"
#include <cuda_runtime.h>
#include <cublas_v2.h>
#include <cstdlib>
#include <filesystem>
#include <iostream>
#include <vector>
namespace {
template<class T> bool Alloc(T**p,std::uint64_t n){return cudaMalloc(reinterpret_cast<void**>(p),n*sizeof(T))==cudaSuccess;}
std::uint64_t Params(mgt_cuda::CudaMlpShape s){return static_cast<std::uint64_t>(s.state_len)*s.state_value_pad*s.hd1+s.hd1+static_cast<std::uint64_t>(s.hd1)*s.hd2+s.hd2+static_cast<std::uint64_t>(s.residual_blocks)*2ULL*(static_cast<std::uint64_t>(s.hd2)*s.hd2+s.hd2)+static_cast<std::uint64_t>(s.hd2)*s.output_dim+s.output_dim;}
}
int main(int argc,char**argv){if(argc!=9){std::cerr<<"usage: device rank world id_file local_rows global_rows warmup steps\n";return 2;}unsigned device=std::strtoul(argv[1],nullptr,10),rank=std::strtoul(argv[2],nullptr,10),world=std::strtoul(argv[3],nullptr,10),lr=std::strtoul(argv[5],nullptr,10),gr=std::strtoul(argv[6],nullptr,10),warmup=std::strtoul(argv[7],nullptr,10),steps=std::strtoul(argv[8],nullptr,10);if(!lr||gr<lr||!steps||world*lr!=gr||device>=world)return 2;if(cudaSetDevice(device)!=cudaSuccess)return 3;mgt_cuda::CudaMlpShape s{mgt::kStateLen,mgt::kStateValuePad,mgt::RoundUp(mgt::kHd1,mgt::kHiddenAlignment),mgt::RoundUp(mgt::kHd2,mgt::kHiddenAlignment),mgt::kResidualBlocks,mgt::kOutputDim};mgt::BatchNormTrainingPlan plan;if(mgt::BuildBatchNormTrainingPlan(mgt::kHd1,mgt::kHd2,s.hd1,s.hd2,s.residual_blocks,lr,&plan)!=mgt::Status::kOk)return 3;auto bn=mgt::InitializeBatchNormTrainingState(plan);std::uint64_t params=Params(s),fw_count=mgt_cuda::MlpBatchNormForwardWorkspaceFloats(s,plan,lr),h2=static_cast<std::uint64_t>(lr)*s.hd2,h1=static_cast<std::uint64_t>(lr)*s.hd1;float *w,*wg,*wm,*wv,*aff,*ag,*am,*av,*running,*out,*fw,*loss,*dy,*block,*fc1,*res,*input,*labels; mgt::TrainStateStorage*states;if(!Alloc(&w,params)||!Alloc(&wg,params)||!Alloc(&wm,params)||!Alloc(&wv,params)||!Alloc(&aff,bn.affine.size())||!Alloc(&ag,bn.affine.size())||!Alloc(&am,bn.affine.size())||!Alloc(&av,bn.affine.size())||!Alloc(&running,bn.running.size())||!Alloc(&out,lr*s.output_dim)||!Alloc(&fw,fw_count)||!Alloc(&loss,1)||!Alloc(&dy,lr*s.output_dim)||!Alloc(&block,h2)||!Alloc(&fc1,h2)||!Alloc(&res,h2)||!Alloc(&input,h1)||!Alloc(&labels,lr*s.output_dim)||!Alloc(&states,lr))return 4;cudaMemset(w,0,params*sizeof(float));cudaMemset(wg,0,params*sizeof(float));cudaMemset(wm,0,params*sizeof(float));cudaMemset(wv,0,params*sizeof(float));cudaMemcpy(aff,bn.affine.data(),bn.affine.size()*sizeof(float),cudaMemcpyHostToDevice);cudaMemset(ag,0,bn.affine.size()*sizeof(float));cudaMemset(am,0,bn.affine.size()*sizeof(float));cudaMemset(av,0,bn.affine.size()*sizeof(float));cudaMemcpy(running,bn.running.data(),bn.running.size()*sizeof(float),cudaMemcpyHostToDevice);cudaMemset(labels,0,lr*s.output_dim*sizeof(float));cudaMemset(states,0,lr*sizeof(mgt::TrainStateStorage));mgt_cuda::NcclRankContext*ctx=nullptr;auto cs=world==1?mgt_cuda::CreateNcclSingleRankContext(device,&ctx):mgt_cuda::CreateNcclRankContext(device,world,rank,std::filesystem::path(argv[4]),&ctx);if(cs!=mgt::Status::kOk)return 5;cublasHandle_t blas=nullptr;cudaStream_t stream=nullptr;cudaEvent_t start=nullptr,stop=nullptr;if(cublasCreate(&blas)!=CUBLAS_STATUS_SUCCESS||cudaStreamCreate(&stream)!=cudaSuccess||cublasSetStream(blas,stream)!=CUBLAS_STATUS_SUCCESS||cudaEventCreate(&start)!=cudaSuccess||cudaEventCreate(&stop)!=cudaSuccess)return 6;mgt_cuda::MlpBatchNormStepBuffers b{w,wg,wm,wv,aff,ag,am,av,running,out,fw,loss,dy,block,fc1,res,input};auto run=[&](std::uint64_t step){mgt_cuda::AdamWKernelConfig adam{params,step,1e-4f,.9f,.999f,1e-8f,0.f};return mgt_cuda::LaunchMlpBatchNormTrainStep(s,mgt::kHd1,mgt::kHd2,states,labels,lr,gr,plan,fw_count,adam,b,ctx,blas,stream);};for(unsigned i=0;i<warmup;i++)if(run(i+1)!=mgt::Status::kOk)return 7;if(cudaStreamSynchronize(stream)!=cudaSuccess||cudaEventRecord(start,stream)!=cudaSuccess)return 8;for(unsigned i=0;i<steps;i++)if(run(warmup+i+1)!=mgt::Status::kOk)return 9;if(cudaEventRecord(stop,stream)!=cudaSuccess||cudaEventSynchronize(stop)!=cudaSuccess)return 10;float ms=0;if(cudaEventElapsedTime(&ms,start,stop)!=cudaSuccess)return 11;cublasMath_t math_mode=CUBLAS_DEFAULT_MATH;if(cublasGetMathMode(blas,&math_mode)!=CUBLAS_STATUS_SUCCESS)return 13;if(rank==0){double step_ms=ms/steps,sps=static_cast<double>(gr)*steps/(ms/1000.0);std::cout<<"{\"world\":"<<world<<",\"global_rows\":"<<gr<<",\"warmup\":"<<warmup<<",\"steps\":"<<steps<<",\"cublas_tf32\":"<<(math_mode==CUBLAS_TF32_TENSOR_OP_MATH?1:0)<<",\"step_ms\":"<<step_ms<<",\"samples_per_second\":"<<sps<<",\"workspace_floats_per_rank\":"<<fw_count<<"}\n";}cublasDestroy(blas);cudaStreamDestroy(stream);return mgt_cuda::DestroyNcclRankContext(ctx)==mgt::Status::kOk?0:12;}